<?php
namespace App\Jobs;use App\Services\Hr\HrReportArtifactService;use App\Services\Hr\HrReportDatasetService;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\Middleware\WithoutOverlapping;use Illuminate\Queue\SerializesModels;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;use Throwable;
class GenerateHrReportArtifact implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int$tries=3;public int$timeout=300;public function __construct(public readonly string$reportRunId){$this->onQueue('exports');}
public function middleware():array{return[(new WithoutOverlapping('hr-report-'.$this->reportRunId))->dontRelease()->expireAfter(600)];}
public function handle(HrReportDatasetService$data,HrReportArtifactService$artifacts):void{$run=DB::table('hr_report_runs')->where('id',$this->reportRunId)->first();if(!$run||in_array($run->status,['completed','expired'],true))return;DB::table('hr_report_runs')->where('id',$run->id)->update(['status'=>'processing','updated_at'=>now()]);if($run->transfer_job_id)DB::table('domain_transfer_jobs')->where('id',$run->transfer_job_id)->update(['state'=>'processing','started_at'=>now(),'updated_at'=>now()]);$view=DB::table('hr_report_saved_views')->where('id',$run->saved_view_id)->where('company_id',$run->company_id)->first();abort_unless($view&&hash_equals($view->view_checksum,hash('sha256',json_encode(['report_kind'=>$view->report_kind,'filters'=>json_decode($view->filter_contract,true)?:[],'columns'=>json_decode($view->column_contract,true)?:[],'visibility'=>$view->visibility],JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR))),409,'Saved report view integrity check failed.');$columns=json_decode($run->column_snapshot,true)?:[];$rows=$data->rows($run,$view);$rendered=$artifacts->render(DB::table('domain_transfer_jobs')->where('id',$run->transfer_job_id)->value('format'),$columns,$rows,$view->name);$file=Str::slug($view->name).'-'.$run->as_of_date.'-'.$run->id.'.'.$rendered['extension'];$path=$run->company_id.'/reports/'.$run->id.'/'.$file;Storage::disk('hr_private')->put($path,$rendered['content']);$checksum=hash('sha256',$rendered['content']);$expires=now()->addDays(max(1,(int)config('hr.report_artifact_retention_days',30)));DB::transaction(function()use($run,$rows,$file,$path,$rendered,$checksum,$expires){DB::table('hr_report_runs')->where('id',$run->id)->update(['status'=>'completed','artifact_disk'=>'hr_private','artifact_path'=>$path,'artifact_file_name'=>$file,'artifact_mime'=>$rendered['mime'],'artifact_size'=>strlen($rendered['content']),'artifact_checksum'=>$checksum,'artifact_expires_at'=>$expires,'completed_at'=>now(),'failure_message'=>null,'updated_at'=>now()]);if($run->transfer_job_id)DB::table('domain_transfer_jobs')->where('id',$run->transfer_job_id)->update(['state'=>'completed','disk'=>'hr_private','path'=>$path,'file_checksum'=>$checksum,'input_rows'=>count($rows),'accepted_rows'=>count($rows),'completed_at'=>now(),'updated_at'=>now()]);DB::table('hr_report_delivery_events')->where('report_run_id',$run->id)->where('event_type','queued')->get()->each(fn($event)=>DB::table('hr_report_delivery_events')->insertOrIgnore(['id'=>(string)Str::uuid(),'report_run_id'=>$run->id,'recipient_user_id'=>$event->recipient_user_id,'channel'=>$event->channel,'event_type'=>'artifact_ready','idempotency_key'=>'hr-report-delivery:'.$run->id.':'.$event->recipient_user_id.':artifact_ready','artifact_checksum'=>$checksum,'actor_user_id'=>config('hr.system_user_id'),'occurred_at'=>now()]));});}
public function failed(Throwable$e):void{DB::table('hr_report_runs')->where('id',$this->reportRunId)->update(['status'=>'failed','failure_message'=>Str::limit($e->getMessage(),4000),'updated_at'=>now()]);$job=DB::table('hr_report_runs')->where('id',$this->reportRunId)->value('transfer_job_id');if($job)DB::table('domain_transfer_jobs')->where('id',$job)->update(['state'=>'failed','failed_at'=>now(),'failure_summary'=>Str::limit($e->getMessage(),4000),'updated_at'=>now()]);}}
